arguments.command:
cd /code && python - <<'PY'
import nbformat, json
nb=nbformat.read('../results/FS-Filters.executed.ipynb', as_version=4)
for i,c in enumerate(nb.cells):
    if c.cell_type=='code' and c.get('outputs'):
        outs=[]
        for o in c.outputs:
            if o.output_type=='stream':
                outs.append(o.text)
            elif o.output_type in ('execute_result','display_data'):
                outs.append(str(o.get('data',{}).get('text/plain','')))
            elif o.output_type=='error':
                outs.append('ERROR:'+o.ename+':'+o.evalue)
        if outs:
            print('CELL',i)
            print(''.join(outs)[:1200])
            print('---')
PY
